size_t fn_15(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {
  size_t need = 0;
  size_t o = 0;
  for (size_t i = 0; i < len;) {
    size_t r;
    for (r = 1; i + r < len && in[i + r] == in[i] && r < 255; r++) {}
    need += 2;
    i += r;
  }
  if (out_cap < need) return (size_t)-1;
  for (size_t i = 0; i < len;) {
    size_t r;
    for (r = 1; i + r < len && in[i + r] == in[i] && r < 255; r++) {}
    out[o++] = (uint8_t)r;
    out[o++] = in[i];
